// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;

    function setUp() public {
        c = new PrivatePool(address(this), address(this), address(this));
    }

    function testFuzz_property(
        address nftAddr,
        address baseTokenAddr,
        uint128 virtualBase,
        uint128 virtualNft,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoyalties
    ) public {
        // keep the deciding value in the admissible domain: nft must be a real,
        // non-zero address so that a correct pool stores it verbatim
        vm.assume(nftAddr != address(0));
        vm.assume(feeRate <= 5_000);

        c.initialize(
            baseTokenAddr,
            nftAddr,
            virtualBase,
            virtualNft,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoyalties
        );

        // General rule: after initialize(_nft), the pool's stored nft equals _nft.
        assertTrue(c.nft() == nftAddr);
    }
}
